import{_ as e,r as s,o,c,e as n,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Фрагменты - October CMS - 3.x","titleTemplate":false,"description":"Повторное использование фрагментов HTML-кода в любом месте сайта.","frontmatter":{"subtitle":"Повторное использование фрагментов HTML-кода в любом месте сайта."},"headers":[{"level":2,"title":"Рендеринг фрагментов","slug":"рендеринг-фрагментов","link":"#рендеринг-фрагментов","children":[]},{"level":2,"title":"Передача переменных во фрагменты","slug":"передача-переменных-во-фрагменты","link":"#передача-переменных-во-фрагменты","children":[{"level":3,"title":"Область видимости переменных","slug":"область-видимости-переменных","link":"#область-видимости-переменных","children":[]},{"level":3,"title":"Парсинг разметки как переменной","slug":"парсинг-разметки-как-переменнои","link":"#парсинг-разметки-как-переменнои","children":[]}]},{"level":2,"title":"Динамические фрагменты","slug":"динамические-фрагменты","link":"#динамические-фрагменты","children":[{"level":3,"title":"Жизненный цикл выполнения фрагмента","slug":"жизненныи-цикл-выполнения-фрагмента","link":"#жизненныи-цикл-выполнения-фрагмента","children":[]},{"level":3,"title":"Вызов AJAX-обработчиков во фрагментах","slug":"вызов-ajax-обработчиков-во-фрагментах","link":"#вызов-ajax-обработчиков-во-фрагментах","children":[{"level":4,"title":"Смотрите также","slug":"смотрите-также","link":"#смотрите-также","children":[]}]}]}],"relativePath":"3.x/ru/cms/themes/partials.md","filePath":"3.x/ru/cms/themes/partials.md"}'),u={name:"3.x/ru/cms/themes/partials.md"};function r(g,a,k,d,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[n(t),a[0]||(a[0]=l("h1",null,"Фрагменты",-1)),n(p),a[1]||(a[1]=i(`<p>Фрагменты — это мощные элементы, позволяющие повторно использовать HTML на разных страницах или макетах, например, подвал страницы, используемый в различных <a href="./layouts.html">макетах страниц</a>. Фрагменты также являются мощным инструментом для динамического <a href="./../ajax/update-partials.html">обновления содержимого страницы с помощью AJAX</a>.</p><p>Файлы шаблонов фрагментов располагаются в каталоге <strong>partials</strong> вашей темы. Файлы фрагментов должны иметь расширение <strong>htm</strong>. Далее приведён пример простейшего фрагмента.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This is a partial<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Секция конфигурации является необязательной для фрагментов и может содержать необязательный параметр <strong>description</strong>, который отображается в интерфейсе администрирования. Этот пример показывает фрагмент с определённым описанием.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">description</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Demo partial</span>&quot;</span>
</code></pre></div><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This is a partial<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Секция конфигурации фрагмента также может содержать определения компонентов. Более подробно компоненты описаны в <a href="./components.html">статье о компонентах</a>.</p><h2 id="рендеринг-фрагментов"><a href="#рендеринг-фрагментов" class="header-anchor">#</a> Рендеринг фрагментов</h2><div class="custom-block aside"><p>Помните, что при обращении к фрагменту из подкаталога необходимо указывать имя подкаталога.</p></div><p>Twig-тег <code>{% partial &quot;partial-name&quot; %}</code> выполняет рендеринг фрагмента. Тег имеет один обязательный параметр — имя файла фрагмента без расширения. Тег <code>{% partial %}</code> может использоваться внутри страницы, макета или другого фрагмента. Ниже приведён пример страницы, ссылающейся на фрагмент.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar-contacts<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="передача-переменных-во-фрагменты"><a href="#передача-переменных-во-фрагменты" class="header-anchor">#</a> Передача переменных во фрагменты</h2><p>Часто возникает необходимость передавать переменные во фрагмент из внешнего кода. Это делает фрагменты ещё более полезными. Например, у вас может быть фрагмент, который выводит список записей блога. Если вы можете передать коллекцию записей во фрагмент, то один и тот же фрагмент можно использовать на странице архива блога, на странице категории блога и так далее. Вы можете передавать переменные во фрагменты, указывая их после имени фрагмента в теге <code>{% partial %}</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>blog-posts<span class="token punctuation">&quot;</span></span> posts<span class="token operator">=</span>posts <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вы также можете предоставлять новые переменные для использования во фрагменте.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar-contacts<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Внутри фрагмента переменные доступны как любые другие переменные разметки.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Country: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>, city: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="область-видимости-переменных"><a href="#область-видимости-переменных" class="header-anchor">#</a> Область видимости переменных</h3><p>Содержимое фрагмента будет иметь доступ к переменным из текущего контекста и дополнительно предоставленным переменным.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> foo<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>bar<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>В следующем примере переменная <code>foo</code> будет доступна внутри шаблона фрагмента <code>mypartial</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> foo <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&quot;</span>bar<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вы можете отключить доступ к контексту, добавив ключевое слово <code>only</code>. В этом примере будет доступна только переменная <code>foo</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> foo<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>bar<span class="token punctuation">&quot;</span></span> only <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>В следующем примере никакие переменные не будут доступны.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>mypartial<span class="token punctuation">&quot;</span></span> only <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="парсинг-разметки-как-переменнои"><a href="#парсинг-разметки-как-переменнои" class="header-anchor">#</a> Парсинг разметки как переменной</h3><p>Можно передать разметку во фрагмент, добавив атрибут <code>body</code> к тегу фрагмента.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    This is the card contents
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Содержимое доступно внутри фрагмента как переменная <code>body</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>В сочетании с <a href="./../../markup/tag/placeholder.html">тегом разметки placeholder</a> это позволяет создавать составные фрагменты.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> image<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>img.jpg<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> header <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>This is the card header<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
    This is the card contents
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Фрагмент <strong>card</strong> состоит из двух областей содержимого и переменной изображения.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>header<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>image<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> image <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> header <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>body<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="динамические-фрагменты"><a href="#динамические-фрагменты" class="header-anchor">#</a> Динамические фрагменты</h2><p>Фрагменты, как и страницы, могут использовать любые возможности Twig. Подробнее см. раздел <a href="./pages.html">Динамические страницы</a> документации.</p><h3 id="жизненныи-цикл-выполнения-фрагмента"><a href="#жизненныи-цикл-выполнения-фрагмента" class="header-anchor">#</a> Жизненный цикл выполнения фрагмента</h3><p>Существуют специальные функции, которые можно определить в секции PHP фрагментов: <code>onStart</code> и <code>onEnd</code>. Функция <code>onStart</code> выполняется перед рендерингом фрагмента и до выполнения <a href="./components.html">компонентов фрагмента</a>. Функция <code>onEnd</code> выполняется перед рендерингом фрагмента и после выполнения компонентов фрагмента. В функциях <code>onStart</code> и <code>onEnd</code> вы можете передавать переменные в окружение Twig. Используйте <code>$this</code> с нотацией массива для передачи переменных на страницу.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code></code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;hello&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string double-quoted-string">&quot;Hello world!&quot;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> hello <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Внешние переменные, назначенные фрагменту, доступны в PHP через объект <code>$this</code>.</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code></code></pre></div><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?</span>
<span class="token keyword">function</span> <span class="token function-definition function">onStart</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;location&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">city</span> <span class="token operator">.</span> <span class="token string single-quoted-string">&#39;, &#39;</span> <span class="token operator">.</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">country</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token delimiter important">?&gt;</span></span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> location <span class="token delimiter punctuation">}}</span></span> is the same as <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>, <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p>Язык шаблонов, предоставляемый October CMS, описан в <a href="./../../markup/templating.html">руководстве по разметке</a>. Общая последовательность выполнения обработчиков описана в разделе <a href="./layouts.html">Динамические макеты</a> документации.</p><h3 id="вызов-ajax-обработчиков-во-фрагментах"><a href="#вызов-ajax-обработчиков-во-фрагментах" class="header-anchor">#</a> Вызов AJAX-обработчиков во фрагментах</h3><p>Поскольку фрагменты инициализируются поздно, во время рендеринга страницы, к жизненному циклу обычных фрагментов применяются некоторые ограничения. Чтобы преодолеть это, вы можете использовать <code>{% ajaxPartial %}</code>, чтобы разрешить вызов AJAX-обработчиков внутри вашего фрагмента.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">ajaxPartial</span> <span class="token string"><span class="token punctuation">&quot;</span>contact-form<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p>Подробнее о теге <code>{% ajaxPartial %}</code> см. в <a href="./../../markup/tag/ajax-partial.html">статье о Twig-теге AJAX Partial</a>.</p></div><p>При вызове обработчика из AJAX-фрагмента жизненный цикл работает иначе по сравнению с обычным AJAX-обработчиком.</p><ol><li>Обработчик выполняется после функции <code>onEnd</code> фрагмента.</li><li>Выполняется полный жизненный цикл страницы, включая логику в макете, на странице и в родительских фрагментах.</li><li>Все переменные доступны во время запроса, включая переменные, установленные с помощью Twig.</li><li>Функции жизненного цикла фрагмента не поддерживают возврат значений.</li></ol><h4 id="смотрите-также"><a href="#смотрите-также" class="header-anchor">#</a> Смотрите также</h4><div class="custom-block also"><ul><li><a href="./../../markup/tag/partial.html">Partial Twig Tag</a></li><li><a href="./../../markup/tag/ajax-partial.html">AJAX Partial Twig Tag</a></li></ul></div>`,51))])}const q=e(u,[["render",r]]);export{v as __pageData,q as default};
